#pragma once
#include "qpm_json.h"
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>
namespace qpm {
class JsonDocument { public: explicit JsonDocument(std::string text,size_t initialTokens=64):text_(std::move(text)){size_t cap=initialTokens?initialTokens:64;for(;;){tokens_.resize(cap);int n=QpmJson_Parse(text_.c_str(),tokens_.data(),tokens_.size());if(n>=0){tokens_.resize(static_cast<size_t>(n));break;} if(n!=-2) throw std::runtime_error("JSON parse failed"); cap*=2;if(cap>1u<<20)throw std::runtime_error("JSON token capacity exceeded");}} int root()const{return tokens_.empty()?-1:0;} int value(int objectIndex,const std::string&key)const{return QpmJson_ObjectValue(text_.c_str(),tokens_.data(),static_cast<int>(tokens_.size()),objectIndex,key.c_str());} int element(int arrayIndex,size_t i)const{return QpmJson_ArrayElement(tokens_.data(),static_cast<int>(tokens_.size()),arrayIndex,i);} std::string string(int token)const{if(token<0||static_cast<size_t>(token)>=tokens_.size())return{};const auto&t=tokens_[token];if(t.type!=QPM_JSON_STRING)return text_.substr(static_cast<size_t>(t.start),static_cast<size_t>(t.end-t.start));std::vector<char> out(static_cast<size_t>(t.end-t.start)*4u+1u);if(QpmJson_GetString(text_.c_str(),&t,out.data(),out.size())!=0)return{};return std::string(out.data());} std::int64_t int64(int token,std::int64_t fallback=0)const{int64_t v=fallback;if(token>=0)QpmJson_GetInt64(text_.c_str(),&tokens_[token],&v);return v;} double number(int token,double fallback=0)const{double v=fallback;if(token>=0)QpmJson_GetDouble(text_.c_str(),&tokens_[token],&v);return v;} bool boolean(int token,bool fallback=false)const{int v=fallback?1:0;if(token>=0)QpmJson_GetBool(text_.c_str(),&tokens_[token],&v);return v!=0;} const QpmJsonToken& token(int i)const{return tokens_.at(static_cast<size_t>(i));} private:std::string text_;std::vector<QpmJsonToken>tokens_;};
class JsonWriter { public: explicit JsonWriter(size_t capacity=4096):buf_(capacity,'\0'){QpmJsonWriter_Init(&w_,buf_.data(),buf_.size());} bool beginObject(){return QpmJsonWriter_BeginObject(&w_)==0;} bool endObject(){return QpmJsonWriter_EndObject(&w_)==0;} bool beginArray(){return QpmJsonWriter_BeginArray(&w_)==0;} bool endArray(){return QpmJsonWriter_EndArray(&w_)==0;} bool key(const std::string&v){return QpmJsonWriter_Key(&w_,v.c_str())==0;} bool value(const std::string&v){return QpmJsonWriter_String(&w_,v.c_str())==0;} bool value(std::int64_t v){return QpmJsonWriter_Int64(&w_,v)==0;} bool value(double v){return QpmJsonWriter_Double(&w_,v)==0;} bool value(bool v){return QpmJsonWriter_Bool(&w_,v?1:0)==0;} bool null(){return QpmJsonWriter_Null(&w_)==0;} std::string str()const{return QpmJsonWriter_Data(&w_)?std::string(QpmJsonWriter_Data(&w_)):std::string{};} private:std::vector<char>buf_;QpmJsonWriter w_{};};
}
